'use strict';
let data, selectedRoute=null, trips=[];
const $=id=>document.getElementById(id), nf=new Intl.NumberFormat('en-US'), money=x=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(x);
const escapeHTML=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').style.display='none',3600);}
function view(id){document.querySelectorAll('.view').forEach(s=>s.hidden=s.id!==id);document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===id);b.setAttribute('aria-current',b.dataset.view===id?'page':'false');});$('crumb').textContent={overview:'Overview',planner:'Plan a ride',trips:'My demo trips',sources:'Data & methodology'}[id];if(id==='trips')renderTrips();window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>view(b.dataset.view)));
function renderOverview(){const m=data.meta;const cards=[['Recorded trips',nf.format(m.valid_rows),'Qualifying January pickups','↗'],['Median total fare',money(m.median_fare),'Per trip · recorded charges','＄'],['Median trip time',m.median_minutes.toFixed(1)+' min','Pickup to drop-off','◷'],['Median distance',m.median_miles.toFixed(2)+' mi','Reported trip distance','⌁']];$('metrics').innerHTML=cards.map(([name,val,note,icon])=>`<div class="metric"><span class="metric-label">${name}</span><span class="metric-icon">${icon}</span><strong>${val}</strong><small>${note}</small></div>`).join('');
const values=data.hourly,max=Math.max(...values),peak=values.indexOf(max),height=125,width=620,bar=16,gap=7,left=37;
let svg=`<svg viewBox="0 0 ${width} 180" role="img" aria-label="Hourly pickup counts across January 2025. Peak hour ${peak}:00 with ${nf.format(max)} pickups.">`;
for(let i=0;i<=3;i++){const y=12+i*height/3;svg+=`<line x1="34" y1="${y}" x2="600" y2="${y}" stroke="#edf0e9"/><text x="27" y="${y+3}" text-anchor="end" fill="#9aa18f" font-size="8">${Math.round(max*(3-i)/3/1000)}k</text>`;}
values.forEach((v,i)=>{const x=left+i*(bar+gap),h=v/max*height;svg+=`<rect x="${x}" y="${height+12-h}" width="${bar}" height="${h}" rx="3" fill="${i===peak?'#76993e':'#c9dfa1'}" tabindex="0"><title>${String(i).padStart(2,'0')}:00 · ${nf.format(v)} pickups</title></rect>`;if(i%3===0)svg+=`<text x="${x+bar/2}" y="157" text-anchor="middle" fill="#939b8b" font-size="9">${String(i).padStart(2,'0')}:00</text>`;});$('hourChart').innerHTML=svg+'</svg>';$('peakNote').textContent=`Peak: ${String(peak).padStart(2,'0')}:00–${String((peak+1)%24).padStart(2,'0')}:00`;
$('topZones').innerHTML=[...data.zones].sort((a,b)=>b.n-a.n).slice(0,5).map((z,i)=>`<div class="zone-row"><span class="rank">0${i+1}</span><span class="zone-name">${escapeHTML(z.name)}<small>${escapeHTML(z.borough)}</small></span><span class="zone-value">${nf.format(z.n)}<small>pickups</small></span></div>`).join('');
const maxHeat=Math.max(...data.heatmap.flat()),days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];let html='<div></div>'+Array.from({length:24},(_,i)=>`<div>${i%3===0?String(i).padStart(2,'0'):''}</div>`).join('');data.heatmap.forEach((row,d)=>{html+=`<div>${days[d]}</div>`+row.map((v,h)=>`<div class="heat-cell" tabindex="0" role="img" aria-label="${days[d]} ${h}:00: ${nf.format(v)} pickups" style="background:hsl(83 36% ${95-v/maxHeat*53}%)"></div>`).join('');});$('heatmap').innerHTML=html;
}
function populateZones(){const zones=[...data.zones].sort((a,b)=>a.name.localeCompare(b.name)),options=zones.map(z=>`<option value="${z.id}">${escapeHTML(z.name)} · ${escapeHTML(z.borough)}</option>`).join('');$('pickup').innerHTML=options;$('dropoff').innerHTML=options;$('pickup').value='161';$('dropoff').value='132';}
function estimate(){const pu=Number($('pickup').value),drop=Number($('dropoff').value),route=MetroCore.findRoute(data.routes,pu,drop);selectedRoute=route;if(pu===drop||!route){$('estimateResult').innerHTML=`<span class="route-symbol">↗</span><h2>${pu===drop?'Choose two different zones':'Not enough historical evidence'}</h2><p>${pu===drop?'Select another destination to compare a zone-to-zone journey.':'This route has fewer than 30 qualifying trips in this snapshot. Try another pair; no fare is estimated.'}</p>`;selectedRoute=null;return;}
const from=data.zones.find(z=>z.id===pu),to=data.zones.find(z=>z.id===drop);$('estimateResult').innerHTML=`<span class="tag" style="color:#7b944e">HISTORICAL ROUTE REFERENCE</span><h2 style="margin-top:12px">${escapeHTML(from.name)} <span style="color:#a8b88f">→</span><br>${escapeHTML(to.name)}</h2><div class="fare-total">${money(route.fare)} <small>median total</small></div><p>Middle 50% of recorded fares: <b>${money(route.low)}–${money(route.high)}</b></p><div class="route-stats"><div><strong>${route.minutes.toFixed(1)} min</strong><small>Median duration</small></div><div><strong>${route.miles.toFixed(1)} mi</strong><small>Median distance</small></div><div><strong>${nf.format(route.n)}</strong><small>Matching trips</small></div></div><button class="primary" id="saveRide">Save demo trip <span>↗</span></button><p class="subtle">January 2025 · USD · Taxi totals, not live quotes. Saving is a local simulation.</p>`;$('saveRide').onclick=()=>{try{trips=MetroCore.saveTrip(localStorage,trips,route,from.name,to.name);$('tripCount').textContent=trips.length;notify('Demo trip saved. View it under My demo trips.');}catch{notify('Could not save. Browser storage may be unavailable or full.');}};
}
function renderTrips(){$('tripCount').textContent=trips.length;if(!trips.length){$('savedTrips').innerHTML='<div class="empty"><span class="route-symbol" style="margin:0 auto 20px">↗</span><h2>No routes saved yet.</h2><p>Plan a route and save your first simulated trip.</p><button class="primary" id="firstRide">Explore routes →</button></div>';$('firstRide').onclick=()=>view('planner');return;}$('savedTrips').innerHTML=trips.map(t=>`<article class="card trip-row"><div><span class="pill">Simulated · ${new Date(t.date).toLocaleDateString('en-GB')}</span><h3 style="font-size:15px;margin-top:16px">${escapeHTML(t.from)} → ${escapeHTML(t.to)}</h3><p>Historical January 2025 median · No real booking</p></div><span class="trip-price">${money(t.fare)}</span><button data-remove="${escapeHTML(t.id)}">Remove</button></article>`).join('');document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const next=trips.filter(t=>t.id!==b.dataset.remove);try{localStorage.setItem('metroride-trips',JSON.stringify(next));trips=next;renderTrips();notify('Demo trip removed.');}catch{notify('Browser storage is unavailable.');}});}
function renderSources(){$('parquetLink').href=data.meta.source;$('zonesLink').href=data.meta.zone_source;$('quality').innerHTML=[['Source records',data.meta.raw_rows],['Retained trips',data.meta.valid_rows],['Excluded trips',data.meta.excluded_rows],['Supported directed routes',data.meta.retained_routes]].map(([label,n])=>`<div class="quality-row"><span>${label}</span><b>${nf.format(n)}</b></div>`).join('');}
$('estimate').onclick=estimate;$('swap').onclick=()=>{const a=$('pickup').value;$('pickup').value=$('dropoff').value;$('dropoff').value=a;if(selectedRoute)estimate();};['pickup','dropoff'].forEach(id=>$(id).onchange=()=>{if(selectedRoute)estimate();});
fetch('data.json').then(r=>{if(!r.ok)throw Error('Data unavailable');return r.json();}).then(d=>{data=d;trips=MetroCore.readTrips(localStorage);renderOverview();populateZones();renderSources();$('tripCount').textContent=trips.length;$('loading').hidden=true;$('content').hidden=false;}).catch(()=>{$('loading').innerHTML='The trip snapshot could not be loaded. <button onclick="location.reload()">Retry</button>';});
